-- Nonnina: full database setup (generated by scripts/supabase/bundle.mjs, do not edit by hand).
-- Migrations: 0001_init.sql, 0002_escalation_and_auth.sql, 0003_help_request_acknowledge.sql, 0004_claim_emergency_event.sql, 0005_marketplace.sql, 0006_helper_photos.sql, 0007_relief_budget.sql
begin;

-- ======== 0001_init.sql ========

-- Nonnina · initial schema
-- Server routes use the service role. The browser only inserts into `waitlist`
-- and reads family data through the anon key for realtime (Layer 2 will add auth).

create extension if not exists "pgcrypto";

-- ---------- enums ----------
create type senior_language as enum ('de', 'it');
create type session_mood as enum ('good', 'ok', 'low', 'worried');
create type help_category as enum ('daily_help', 'legal', 'money', 'health', 'loneliness', 'other');
create type help_status as enum ('open', 'ai_solved', 'escalated', 'matched');
create type emergency_level as enum ('emergency', 'warning');
create type emergency_source as enum ('agent_tool', 'keyword_detector', 'manual_button', 'no_response');
create type emergency_status as enum ('open', 'relatives_notified', 'acknowledged', 'cancelled_by_senior');
-- waitlist may already exist when the landing page ran first against this project (supabase/waitlist.sql)
do $$ begin
  create type waitlist_role as enum ('family', 'helper', 'care_service', 'other');
exception when duplicate_object then null; end $$;

-- ---------- tables ----------
create table families (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  email text,
  created_at timestamptz not null default now()
);

create table relatives (
  id uuid primary key default gen_random_uuid(),
  family_id uuid not null references families(id) on delete cascade,
  name text not null,
  relation text not null,
  phone text check (phone is null or phone ~ '^\+[1-9][0-9]{6,14}$'),
  email text,
  notify_sms boolean not null default true,
  notify_call boolean not null default false,
  priority int not null default 1 check (priority >= 1)
);
create index relatives_family_idx on relatives(family_id, priority);

create table seniors (
  id uuid primary key default gen_random_uuid(),
  family_id uuid not null references families(id) on delete cascade,
  first_name text not null,
  language senior_language not null default 'de',
  city text not null,
  address_note text,
  care_level int not null default 0 check (care_level between 0 and 5),
  device_token text not null unique default encode(gen_random_bytes(12), 'hex'),
  medication_times jsonb not null default '[]'::jsonb,
  created_at timestamptz not null default now()
);
create index seniors_family_idx on seniors(family_id);

create table voice_sessions (
  id uuid primary key default gen_random_uuid(),
  senior_id uuid not null references seniors(id) on delete cascade,
  conversation_id text,
  summary text,
  mood session_mood,
  problem_category text,
  needs_human boolean not null default false,
  created_at timestamptz not null default now()
);
create index voice_sessions_senior_idx on voice_sessions(senior_id, created_at desc);
create unique index voice_sessions_conversation_idx on voice_sessions(conversation_id) where conversation_id is not null;

create table help_requests (
  id uuid primary key default gen_random_uuid(),
  senior_id uuid not null references seniors(id) on delete cascade,
  category help_category not null default 'other',
  summary text not null,
  status help_status not null default 'open',
  created_at timestamptz not null default now()
);
create index help_requests_senior_idx on help_requests(senior_id, created_at desc);

create table emergency_events (
  id uuid primary key default gen_random_uuid(),
  senior_id uuid not null references seniors(id) on delete cascade,
  level emergency_level not null,
  reason text not null,
  quote text,
  source emergency_source not null,
  status emergency_status not null default 'open',
  notified jsonb not null default '[]'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index emergency_events_senior_idx on emergency_events(senior_id, created_at desc);

create table if not exists waitlist (
  id uuid primary key default gen_random_uuid(),
  email text not null unique,
  role waitlist_role not null default 'other',
  city text,
  message text,
  created_at timestamptz not null default now()
);

-- ---------- row level security ----------
alter table families enable row level security;
alter table relatives enable row level security;
alter table seniors enable row level security;
alter table voice_sessions enable row level security;
alter table help_requests enable row level security;
alter table emergency_events enable row level security;
alter table waitlist enable row level security;

-- Anonymous visitors may join the waitlist (insert only, never read).
drop policy if exists "waitlist_anon_insert" on waitlist;
create policy "waitlist_anon_insert" on waitlist for insert to anon with check (true);

-- Prototype: the family alerts page is a link-protected read-only view (the familyId is the secret).
-- Layer 2 replaces these with auth-based policies.
create policy "events_anon_read" on emergency_events for select to anon using (true);
create policy "help_requests_anon_read" on help_requests for select to anon using (true);
create policy "voice_sessions_anon_read" on voice_sessions for select to anon using (true);

-- ---------- realtime ----------
alter publication supabase_realtime add table emergency_events;
alter publication supabase_realtime add table help_requests;
alter publication supabase_realtime add table voice_sessions;


-- ======== 0002_escalation_and_auth.sql ========

-- Nonnina · 0002 escalation ladder + family auth
-- Adds: families.fallback_phone, relatives.user_id (Supabase Auth link),
-- emergency_events escalation columns, help_requests.resolved_at,
-- and RLS policies for authenticated family members.

-- ---------- columns ----------
alter table families
  add column fallback_phone text check (fallback_phone is null or fallback_phone ~ '^\+[1-9][0-9]{6,14}$');

alter table relatives
  add column user_id uuid references auth.users(id) on delete set null;
create index relatives_user_idx on relatives(user_id);

alter table emergency_events
  add column escalation_step int not null default 0,
  add column next_step_at timestamptz,
  add column acknowledged_by uuid references relatives(id) on delete set null;
create index emergency_events_due_idx on emergency_events(status, next_step_at);

alter table help_requests
  add column resolved_at timestamptz;

-- ---------- auth helper ----------
-- Families the current auth user belongs to (through a relatives row).
create or replace function public.my_family_ids()
returns setof uuid
language sql
stable
security definer
set search_path = public
as $$
  select family_id from relatives where user_id = auth.uid();
$$;
revoke all on function public.my_family_ids() from public;
grant execute on function public.my_family_ids() to authenticated;

-- ---------- RLS for authenticated family members ----------
create policy "families_member_read" on families
  for select to authenticated
  using (id in (select public.my_family_ids()));

create policy "relatives_member_read" on relatives
  for select to authenticated
  using (family_id in (select public.my_family_ids()));

create policy "seniors_member_read" on seniors
  for select to authenticated
  using (family_id in (select public.my_family_ids()));

create policy "voice_sessions_member_read" on voice_sessions
  for select to authenticated
  using (senior_id in (select id from seniors where family_id in (select public.my_family_ids())));

create policy "help_requests_member_read" on help_requests
  for select to authenticated
  using (senior_id in (select id from seniors where family_id in (select public.my_family_ids())));

create policy "emergency_events_member_read" on emergency_events
  for select to authenticated
  using (senior_id in (select id from seniors where family_id in (select public.my_family_ids())));

-- Writes go through server routes (service role). These update policies are kept for future
-- browser-side acknowledge / resolve; they are not used today.
create policy "help_requests_member_update" on help_requests
  for update to authenticated
  using (senior_id in (select id from seniors where family_id in (select public.my_family_ids())))
  with check (senior_id in (select id from seniors where family_id in (select public.my_family_ids())));

create policy "emergency_events_member_update" on emergency_events
  for update to authenticated
  using (senior_id in (select id from seniors where family_id in (select public.my_family_ids())))
  with check (senior_id in (select id from seniors where family_id in (select public.my_family_ids())));

-- NOTE: the anon read policies from 0001 (events_anon_read, help_requests_anon_read,
-- voice_sessions_anon_read) stay in place because /demo still reads through the anon key.
-- Remove them in a later migration once the demo page uses a token-protected feed.

-- ---------- realtime ----------
-- Relatives are read by the family app; add them to the publication so settings refresh live.
alter publication supabase_realtime add table relatives;


-- ======== 0003_help_request_acknowledge.sql ========

-- Nonnina · 0003 help request "I'm on it"
-- A relative takes a non-urgent help request from the family feed; the senior tablet then
-- shows "Anna kümmert sich um: …". Mirrors HelpRequest.acknowledged_by / acknowledged_at
-- in lib/db/types.ts.

alter table help_requests
  add column acknowledged_by uuid references relatives(id) on delete set null,
  add column acknowledged_at timestamptz;

-- The tablet polls the latest acknowledged, unresolved request of its senior.
create index help_requests_ack_idx on help_requests(senior_id, acknowledged_at desc)
  where acknowledged_at is not null;


-- ======== 0004_claim_emergency_event.sql ========

-- Atomic open of an emergency event.
-- Two taps at once take one row: the lock is held for the check and the insert.
-- Called by SupabaseStore.claimEmergencyEvent (lib/db/supabase-store.ts).
-- Reads and writes emergency_events. No new columns.

create or replace function claim_emergency_event(
  p_senior_id uuid,
  p_level emergency_level,
  p_reason text,
  p_quote text,
  p_source emergency_source,
  p_since timestamptz
) returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  existing public.emergency_events%rowtype;
  created public.emergency_events%rowtype;
begin
  perform pg_advisory_xact_lock(hashtext(p_senior_id::text));

  select * into existing
  from public.emergency_events
  where senior_id = p_senior_id
    and status <> 'cancelled_by_senior'
    and created_at >= p_since
  order by created_at desc
  limit 1;

  if found and (existing.level = p_level or existing.level = 'emergency') then
    return jsonb_build_object('created', false, 'event', to_jsonb(existing));
  end if;

  insert into public.emergency_events (senior_id, level, reason, quote, source, status, notified)
  values (p_senior_id, p_level, p_reason, p_quote, p_source, 'open', '[]'::jsonb)
  returning * into created;

  return jsonb_build_object('created', true, 'event', to_jsonb(created));
end;
$$;

revoke all on function claim_emergency_event(uuid, emergency_level, text, text, emergency_source, timestamptz) from public, anon, authenticated;
grant execute on function claim_emergency_event(uuid, emergency_level, text, text, emergency_source, timestamptz) to service_role;


-- ======== 0005_marketplace.sql ========

-- Nonnina · 0005 marketplace (Layer 3)
-- helpers: people, services and volunteers who offer help (shopping, cooking, company …).
-- helper_requests: a family asks a helper for a service; accept → contacts are shared,
-- linked help_requests go to status 'matched'.
-- Mirrors Helper / HelperRequest in lib/db/types.ts. Writes go through server actions /
-- routes with the service role only.

create type helper_kind as enum ('independent', 'service', 'volunteer');
create type helper_request_status as enum ('sent', 'accepted', 'declined', 'done');

create table helpers (
  id uuid primary key default gen_random_uuid(),
  user_id uuid references auth.users(id) on delete set null,
  name text not null check (char_length(name) between 2 and 80),
  kind helper_kind not null default 'independent',
  city text not null,
  bio text not null default '',
  languages text[] not null default '{}',
  services text[] not null default '{}' check (
    services <@ array['shopping', 'cooking', 'company', 'household', 'transport', 'appointments',
                      'paperwork', 'personal_care', 'gardening', 'tech_help']::text[]
  ),
  hourly_rate_eur numeric(6, 2) check (hourly_rate_eur is null or hourly_rate_eur >= 0),
  phone text check (phone is null or phone ~ '^\+[1-9][0-9]{6,14}$'),
  email text,
  verified boolean not null default false,
  active boolean not null default true,
  created_at timestamptz not null default now()
);
create unique index helpers_user_idx on helpers(user_id) where user_id is not null;
create index helpers_city_idx on helpers(lower(city)) where active;
create index helpers_services_idx on helpers using gin (services);

create table helper_requests (
  id uuid primary key default gen_random_uuid(),
  family_id uuid not null references families(id) on delete cascade,
  senior_id uuid not null references seniors(id) on delete cascade,
  helper_id uuid not null references helpers(id) on delete cascade,
  relative_id uuid references relatives(id) on delete set null,
  help_request_id uuid references help_requests(id) on delete set null,
  service text not null check (
    service in ('shopping', 'cooking', 'company', 'household', 'transport', 'appointments',
                'paperwork', 'personal_care', 'gardening', 'tech_help')
  ),
  message text not null default '' check (char_length(message) <= 600),
  preferred_time text check (preferred_time is null or char_length(preferred_time) <= 120),
  status helper_request_status not null default 'sent',
  notified jsonb not null default '[]'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index helper_requests_helper_idx on helper_requests(helper_id, created_at desc);
create index helper_requests_family_idx on helper_requests(family_id, created_at desc);

-- ---------- row level security ----------
alter table helpers enable row level security;
alter table helper_requests enable row level security;

-- Public directory: anyone may read active helpers, but only the safe columns.
-- Column privileges hide phone, email and user_id from anon / authenticated even with RLS.
revoke all on helpers from anon, authenticated;
grant select (id, name, kind, city, bio, languages, services, hourly_rate_eur, verified, active, created_at)
  on helpers to anon, authenticated;
create policy "helpers_public_read" on helpers
  for select to anon, authenticated
  using (active);

-- Convenience view for clients (and the voice agent later): same safe columns, active only.
create view helpers_public with (security_invoker = true) as
  select id, name, kind, city, bio, languages, services, hourly_rate_eur, verified, created_at
  from helpers
  where active;
grant select on helpers_public to anon, authenticated;

-- Helper requests: family members read their family's rows, a helper reads requests sent to them.
revoke all on helper_requests from anon;
create policy "helper_requests_family_read" on helper_requests
  for select to authenticated
  using (family_id in (select public.my_family_ids()));

create or replace function public.my_helper_ids()
returns setof uuid
language sql
stable
security definer
set search_path = public
as $$
  select id from helpers where user_id = auth.uid();
$$;
revoke all on function public.my_helper_ids() from public;
grant execute on function public.my_helper_ids() to authenticated;

create policy "helper_requests_helper_read" on helper_requests
  for select to authenticated
  using (helper_id in (select public.my_helper_ids()));

-- No insert / update / delete policies: writes use the service role (server actions).


-- ======== 0006_helper_photos.sql ========

-- Nonnina · 0006 helper photos + demo flag
-- photo_url: public profile photo (relative path like /helpers/<slug>.jpg or an absolute URL).
-- is_demo: true for seeded showcase profiles; the directory shows a "Demo profile" label.
-- Mirrors Helper.photo_url / Helper.is_demo in lib/db/types.ts.

alter table helpers add column photo_url text check (photo_url is null or char_length(photo_url) <= 500);
alter table helpers add column is_demo boolean not null default false;

-- Both are public: extend the column grant from 0005 (phone, email, user_id stay hidden).
grant select (photo_url, is_demo) on helpers to anon, authenticated;

-- Recreate the public view with the new columns (column list changes, so drop + create).
drop view if exists helpers_public;
create view helpers_public with (security_invoker = true) as
  select id, name, kind, city, bio, languages, services, hourly_rate_eur, verified, photo_url, is_demo, created_at
  from helpers
  where active;
grant select on helpers_public to anon, authenticated;


-- ======== 0007_relief_budget.sql ========

-- Nonnina · 0007 relief budget (Entlastungsbetrag)
-- helpers.relief_eligible: the helper can be paid via the relief amount (131 €/month from care
--   level 1; in Baden-Württemberg only recognised "Angebote zur Unterstützung im Alltag" /
--   approved care services). Set by the Nonnina team, public like `verified`.
-- helper_requests: completion fields. A request in status 'done' with an amount is a completed,
--   billable job; the family dashboard sums these per month (lib/relief-budget.ts).
-- Mirrors Helper.relief_eligible and HelperRequest.hours / amount_eur / service_date / completed_at
-- in lib/db/types.ts.

alter table helpers add column relief_eligible boolean not null default false;

-- Public like verified: extend the column grant from 0005/0006 and recreate the public view.
grant select (relief_eligible) on helpers to anon, authenticated;

drop view if exists helpers_public;
create view helpers_public with (security_invoker = true) as
  select id, name, kind, city, bio, languages, services, hourly_rate_eur, verified, relief_eligible, photo_url, is_demo, created_at
  from helpers
  where active;
grant select on helpers_public to anon, authenticated;

alter table helper_requests
  add column hours numeric(5, 2) check (hours is null or (hours > 0 and hours <= 24)),
  add column amount_eur numeric(8, 2) check (amount_eur is null or amount_eur >= 0),
  add column service_date date,
  add column completed_at timestamptz;

-- Completion data only makes sense for finished jobs.
alter table helper_requests add constraint helper_requests_completion_done
  check (status = 'done' or (hours is null and amount_eur is null and service_date is null and completed_at is null));

create index helper_requests_done_idx on helper_requests(family_id, service_date) where status = 'done';

-- ---------- row level security ----------
-- The app writes with the service role (server actions check ownership). These policies let a
-- signed-in family member or helper record a completion directly as well: only the completion
-- columns are updatable, only on their own rows, and only to status 'done'.
-- Supabase grants table-wide update to authenticated by default: narrow it to these columns.
revoke insert, update, delete on helper_requests from authenticated;
grant update (status, hours, amount_eur, service_date, completed_at, updated_at) on helper_requests to authenticated;

create policy "helper_requests_family_complete" on helper_requests
  for update to authenticated
  using (family_id in (select public.my_family_ids()) and status in ('accepted', 'done'))
  with check (family_id in (select public.my_family_ids()) and status = 'done');

create policy "helper_requests_helper_complete" on helper_requests
  for update to authenticated
  using (helper_id in (select public.my_helper_ids()) and status in ('accepted', 'done'))
  with check (helper_id in (select public.my_helper_ids()) and status = 'done');


